//Generated by AI

using UnityEngine;
using TMPro;

public class TrashPickup : MonoBehaviour
{
    public TMP_Text objectiveText;

    [Header("Pickup Sound")]
    public AudioClip pickupSound;

    [Range(0f, 1f)]
    public float soundVolume = 1f;

    [Header("Accessibility")]
    private SubtitleController subtitleController;

    private string pickupMessage =
        "Waste collected!";

    // Shared counters for all trash pickup objects.
    private static int trashCount = 0;
    private static int totalTrash = 0;

    private bool collected = false;
    private bool playerInRange = false;

    // References the trash object currently available for collection.
    public static TrashPickup nearbyTrash;

    // Reset static counters when the game session starts.
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    private static void ResetCounter()
    {
        trashCount = 0;
        totalTrash = 0;
    }

    private void Start()
    {
        // Find the subtitle system available in the scene.
        subtitleController =
            FindFirstObjectByType<SubtitleController>();

        // Initialize the total number of trash objects in the scene.
        if (totalTrash == 0)
        {
            totalTrash = FindObjectsByType<TrashPickup>(
                FindObjectsSortMode.None).Length;
        }

        UpdateCounter();
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        // Register the player when entering the collection range.
        if (other.CompareTag("Player"))
        {
            playerInRange = true;
            nearbyTrash = this;
        }
    }

    private void OnTriggerExit2D(Collider2D other)
    {
        // Clear the current collectible when the player leaves its range.
        if (other.CompareTag("Player"))
        {
            playerInRange = false;

            if (nearbyTrash == this)
            {
                nearbyTrash = null;
            }
        }
    }

    // Public method to refresh the objective counter externally.
    public void RefreshCounter()
    {
        UpdateCounter();
    }

    // Update the UI with the remaining trash and purifier objectives.
    private void UpdateCounter()
    {
        if (objectiveText != null)
        {
            int remainingTrash = totalTrash - trashCount;

            int purifierCount =
                PurificationTrigger.purifierCollected ? 0 : 1;

            objectiveText.text =
                "x" + remainingTrash + "      x" + purifierCount;
        }
    }

    // Collects the trash object when the player explicitly interacts with it.
    public void Collect()
    {
        // Ignore repeated collection attempts.
        if (collected)
            return;

        // Require the player to be inside the collection range.
        if (!playerInRange)
            return;

        collected = true;

        trashCount++;

        // Play the pickup sound at the object's position.
        if (pickupSound != null)
        {
            AudioSource.PlayClipAtPoint(
                pickupSound,
                transform.position,
                soundVolume
            );
        }

        // Display the collection message.
        if (subtitleController != null)
        {
            subtitleController.ShowSubtitle(
                pickupMessage
            );
        }

        UpdateCounter();

        Debug.Log("WASTE COLLECTED");
        Debug.Log(
            "Remaining waste: " +
            (totalTrash - trashCount)
        );

        gameObject.SetActive(false);
    }
}